{
  "returncode": 0,
  "output_head": "require "application_system_test_case"

class ModeratorFlowTest < ApplicationSystemTestCase
  setup do
    @orig_user = ENV["QUIZZY_MODERATOR_USERNAME"]
    @orig_pass = ENV["QUIZZY_MODERATOR_PASSWORD"]
    ENV["QUIZZY_MODERATOR_USERNAME"] = "moderator"
    ENV["QUIZZY_MODERATOR_PASSWORD"] = "conf2026"
  end

  teardown do
    ENV["QUIZZY_MODERATOR_USERNAME"] = @orig_user
    ENV["QUIZZY_MODERATOR_PASSWORD"] = @orig_pass
  end

  def login_as_moderator!
  auth = ActionController::HttpAuthentication::Basic.encode_credentials("moderator", "conf2026")
  page.driver.browser.headers.set("Authorization" => auth)
end

  test "unauthenticated request to /moderate gets 401 while / and /up get 200" do
  page.driver.browser.headers.clear
  visit "/up"
  assert_equal 200, page.status_code

  visit "/"
  assert_equal 200, page.status_code

  err = assert_raises(Ferrum::StatusError) { visit "/moderate" }
  assert_includes err.message, "ERR_INVALID_AUTH_CREDENTIALS"
end

  test "creating, editing settings, and deleting quizzes with confirmation" do
    login_as_moderator!
    visit "/moderate"

    # Check design stylesheet is applied (lavender background #e9e6ff -> rgb(233, 230, 255))
    bg_color = page.evaluate_script("getComputedStyle(document.body).backgroundColor")
    assert_equal "rgb(233, 230, 255)", bg_color

    click_button "New quiz"

    # Blank title fails validation and stays on form
    click_button "Save quiz"
    assert_equal 0, Quiz.count

    fill_in "Title", with: "Frontend Fest \"2026\" & Beyond"
    click_button "Save quiz"

    # Opens quiz page
    assert_selector "h1", text: "Frontend Fest \"2026\" & Beyond"
    assert_button "Add question"
    assert_link "Settings"
    assert_link "Preview"

    # Create a second quiz and verify /moderate lists each quiz in its own list item
    visit "/moderate"
    click_button "New quiz"
    fill_in "Title", with: "Rails World Trivia"
    click_button "Save quiz"

    visit "/moderate"
    quiz_items = all("li")
    assert_equal 2, quiz_items.size
    assert_text "Frontend Fest \"2026\" & Beyond"
    assert_text "Rails World Trivia"

    within(find("li", text: "Frontend Fest")) do
      click_link "Frontend Fest \"2026\" & Beyond"
    end

    # Settings updates quiz and returns to quiz page
    click_link "Settings"
    assert_field "Title", with: "Frontend Fest \"2026\" & Beyond"
    fill_in "Title", with: "Frontend Fest 2026 Updated"
    click_button "Save quiz"
    assert_selector "h1", text: "Frontend Fest 2026 Updated"

    # Delete quiz asks for native confirm(): dismissing keeps quiz, accepting deletes it
    click_link "Settings"
    dismiss_confirm do
      click_button "Delete quiz"
    end
    assert_equal 2, Quiz.count

    accept_confirm do
      click_button "Delete quiz"
    end

    assert_current_path "/moderate"
    assert_no_text "Frontend Fest 2026 Updated"
    assert_text "Rails World Trivia"
    assert_equal 1, Quiz.count
  end

  test "question form defaults, add option, validation rules, and preserving moderator input on new and edit" do
    quiz = Quiz.create!(title: "Architecture Talk")
    login_as_moderator!
    visit moderate_quiz_path(quiz)

    click_button "Add question"

    # Starts with 4 empty option rows and Active checked by default
    assert_field "Question", with: ""
    (1..4).each do |n|
      assert_field "Option #{n}", with: ""
      assert_unchecked_field "Option #{n} is correct"
    end
    assert_no_field "Option 5"
    assert_checked_field "Active"

    # Add option adds Option 5
    fill_in "Question", with: "Which \"databases\" are relational?"
    fill_in "Option 1", with: "PostgreSQL"
    click_button "Add option"
    assert_field "Option 5", with: ""
    assert_unchecked_field "Option 5 is correct"
    assert_field "Option 1", with: "PostgreSQL"

    # Rule 1: Needs at least two non-empty options (Option 1 only + empty rows)
    check "Option 1 is correct"
    uncheck "Active"
    click_button "Save question"

    assert_text "Add at least two options"
    assert_equal 0, Question.count
    assert_field "Question", with: "Which \"databases\" are relational?"
    assert_field "Option 1", with: "PostgreSQL"
    assert_checked_field "Option 1 is correct"
    assert_field "Option 5", with: ""
    assert_unchecked_field "Active"

    # Add option again after 422 re-render adds Option 6
    click_button "Add option"
    assert_field "Option 6", with: ""
    assert_unchecked_field "Option 6 is correct"

    # Rule 2: At least one NON-EMPTY option must be correct
    uncheck "Option 1 is correct"
    check "Option 2 is correct" # Option 2 is empty -> skipped!
